      '1': [0, 95945, 97864, 99821, 101818, 103854, 105931, 108050, 110211, 112415, 114663, 116957, 119296, 121682, 124115, 126598],
      '2': [0, 103130, 105193, 107296, 109442, 111631, 113864, 116141, 118464, 120833, 123250, 125715, 128229, 130794, 133410, 136078],
      '3': [0, 114258, 116543, 118874, 121252, 123677, 126150, 128673, 131247, 133872, 136549, 139280, 142066, 144907, 147805, 150761],
      '4': [0, 125026, 127527, 130077, 132679, 135332, 138039, 140800, 143616, 146488, 149418, 152406, 155454, 158563, 161735, 164969],
      '5': [0, 137357, 140104, 142906, 145764, 148679, 151653, 154686, 157780, 160935, 164154, 167437, 170786, 174202, 177686, 181239],
